use std::fs

trait Pricing {
    fn total(self, qty: int, unit: int) -> int
}

struct Plain {}
struct Bulk {}
struct Member {}

impl Pricing for Plain {
    fn total(self, qty: int, unit: int) -> int {
        qty * unit
    }
}

impl Pricing for Bulk {
    fn total(self, qty: int, unit: int) -> int {
        let t = qty * unit
        if qty >= 10 { t - t * 10 / 100 } else { t }
    }
}

impl Pricing for Member {
    fn total(self, qty: int, unit: int) -> int {
        let t = qty * unit
        let mut r = t - t * 5 / 100
        if qty >= 3 { r -= 100 }
        if r < 0 { 0 } else { r }
    }
}

fn fmt(c: int) -> string {
    let d = c / 100
    let r = c % 100
    let sign = "$"
    if r < 10 { "${sign}${d}.0${r}" } else { "${sign}${d}.${r}" }
}

fn price(kind: string, qty: int, unit: int) -> Option<int> {
    if kind == "plain" {
        Some(Plain {}.total(qty, unit))
    } else if kind == "bulk" {
        Some(Bulk {}.total(qty, unit))
    } else if kind == "member" {
        Some(Member {}.total(qty, unit))
    } else {
        None
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut sum = 0
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 4 { continue }
        let qty: int = parts[1].parse().unwrap_or(0)
        let unit: int = parts[2].parse().unwrap_or(0)
        match price(parts[3], qty, unit) {
            Some(t) => {
                sum += t
                println("${parts[0]} ${fmt(t)}")
            }
            None => println("${parts[0]} invalid kind")
        }
    }
    println("total ${fmt(sum)}")
}

